    # Intersection of all remaining sets
    remaining_sets = [set(rem) for rem in remaining_lists]
    if remaining_sets:
        unclaimed_set = set.intersection(*remaining_sets)
    else:
        unclaimed_set = set()

    # Preserve original order and duplicates
    unclaimed = [arg for arg in unparsed_arguments if arg in unclaimed_set]

    return parsed_results, unclaimed

