    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    result = {}
    for child in node:
        key = child.tag
        if key in result:
            # If already a list, append; otherwise convert to list
            if isinstance(result[key], list):
                result[key].append(child)
            else:
                result[key] = [result[key], child]
        else:
            result[key] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Default NodeInfo document path
    if document_path is None:
        document_path = "/nodeinfo/2.0"

    # Ensure the base URL does not end with a slash
    base = url.rstrip('/')

    # Ensure the document path starts with a slash
    if not document_path.startswith('/'):
        document_path = '/' + document_path

    href = base + document_path

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        import base64
        from cryptography.hazmat.primitives import serialization, hashes
        from cryptography.hazmat.primitives.asymmetric import padding
    except Exception:
        # Required libraries are not available
        return False

    # Load the public key (PEM format expected)
    try:
        if isinstance(public_key, str):
            key_bytes = public_key.encode()
        else:
            key_bytes = public_key
        pub_key = serialization.load_pem_public_key(key_bytes)
    except Exception:
        return False

    # Compute the hash of the document
    try:
        if isinstance(doc, str):
            doc_bytes = doc.encode()
        else:
            doc_bytes = doc
        digest = hashes.Hash(hashes.SHA256())
        digest.update(doc_bytes)
        doc_hash = digest.finalize()
    except Exception:
        return False

    # Decode the provided signature (base64 encoded)
    try:
        sig_bytes = base64.b64decode(signature)
    except Exception:
        return False

    # Verify the signature
    try:
        pub_key.verify(
            sig_bytes,
            doc_hash,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        return False

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if '@' not in handle:
            return None
        domain = handle.split('@', 1)[1]
        resource = f'acct:{handle}'
        import urllib.parse
        import urllib.request
        url = f'https://{domain}/.well-known/webfinger?resource={urllib.parse.quote(resource)}'
        with urllib.request.urlopen(url, timeout=5) as resp:
            if resp.status != 200:
                return None
            return resp.read().decode('utf-8')
    except Exception:
        return None

